insert into public.monkeys
    (name, sex, chip, troop_id, birth_year, photos, bio, description)
select v.name, v.sex, v.chip, t.id, v.birth_year, v.photos, v.bio, v.description
from (values
    ('Aroha', 'male', '19806', 'H&B', 2016, array['https://i.ibb.co/smzxJ28/aroha-james-oct2023-min.webp']::text[], 'Arrived as an orphan in 2016.', ''),
    ('Ayeshe', 'female', '8645', 'James', 2015, array['https://i.ibb.co/vJTt5m1/ayeshe-james-nov2022-min.webp']::text[], 'Arrived Jan 2016 as a young orphan from Phalaborwa, she was found in a toilet block of a lodge and could have been there for up to 3 days, dehydrated and traumatised. Refused to drink milk in baby care & suffered ill health from an early age. Fostered by Litchie.', ''),
    ('Briyani', 'female', '21128', 'James', 2008, array['https://i.ibb.co/7r5RBFw/briyani-james-oct2023-min.webp']::text[], 'DOB unknown, min 2006. Arrived as an ex-pet. Originally in Sickbay troop but removed with Emblem in 2009 due to suspected TB and then integrated into James in 2011 with Emblem.', ''),
    ('Charlotte', 'female', '26521', 'James', 2020, array['https://i.ibb.co/71xD5xF/charlotte-james-apr2024-min.webp']::text[], 'Arrived July 2021 having been shot in the head with a pellet gun. Pellets were removed but has some lasting mild brain damage. Slight delay on right side. Originally integrated into Gismo but sustained two further head injuries so moved to James, and integrated May 2022.', ''),
    ('Darby', 'male', '41200', 'James', 2023, array['https://i.ibb.co/gyWCTvJ/darby-james-may2024-2-min.webp', 'https://i.ibb.co/TcByhLx/darby-james-may2024-min.webp']::text[], 'Arrived Oct 2023, found in an office building in Nelspurit after a long weekend. Arrived with a badly broken right arm, a Salter Harris fracture. Does not have full function (extension) of right arm as a result. Integrated into troop Feb 2024 with foster-mum Litchie.', ''),
    ('Eliza', 'female', '21693', 'James', 2017, array['https://i.ibb.co/G5Js3C0/eliza-james-may2024-min.webp']::text[], 'Born 2017. Arrived as an orphan, was kept as a pet for 6 months, very humanised. Started foster-mum integrations at D&D but due was very scared of the monkeys and wasn’t doing well so moved to James. Integrated in Aug 2018.', ''),
    ('Emblem', 'female', '1724', 'James', 2006, array['https://i.ibb.co/pfW96kb/emblem-james-may2022-min.webp']::text[], 'DOB unknown, min 2006. Arrived as an ex-pet. Originally in Sickbay troop but removed with Briyani in 2009 due to suspected TB and then integrated into James in 2011 with Briyani. Low-ranked', ''),
    ('Gimli', 'male', '26690', 'James', 2019, array['https://i.ibb.co/F6CJ2mZ/gimli-james-mar2024-min.webp']::text[], 'Arrived on Feb 2020 after being found alone in a warehouse, extremely traumatised. Spent months curled up in a ball, not interacting. Had very ill health and took months to learn to drink milk. Came out of his shell once he met Litchie during foster-mums integrations.', ''),
    ('Juno', 'female', '1679', 'James', 2007, array['https://i.ibb.co/NWt5mMr/juno-james-apr2024-min.webp']::text[], 'Born 2007. Originally from Sickbay troop (now known as Global) but used to jump in & out of James and then eventually stayed there in 2010.', ''),
    ('Litchie', 'female', '1670', 'James', 2004, array['https://i.ibb.co/68CcM1P/litchi-james-feb2024-min.webp']::text[], 'Born approx. 2004. Arrived in 2008 at around 3-4 years old as an ex-pet. Very humanised and can be very aggressive. Main foster-mum of the troop. Fostered Ayeshe, Gimli, Teo, Beau, and Darby.', ''),
    ('Luna', 'female', '26738', 'James', 2019, array['https://i.ibb.co/YpRm2Pt/luna-james-feb2024-min.webp']::text[], 'Arrived Dec 2019, was kept as a pet with bush babies. Seemed to have neurological issues on arrival, falling in and out of consciousness, which last several days. Integrated with foster-mum Emblem Feb 2020.', ''),
    ('Ozge', 'female', '26583', 'James', 2020, array['https://i.ibb.co/GJV8Ppv/ozgo-james-may2024-min.webp']::text[], 'Arrived Jun 2021 from Johannesburg Wildlife Vet. Has mild brain damage and delay on the right side due to people trying to stone her. High ranked. Will bite babies(?).', ''),
    ('Serala', 'female', '26697', 'James', 2022, array['https://i.ibb.co/tD79SnN/serala-james-may2024-min.webp']::text[], 'Arrived Mar 2022, with skull fracture and abscess. Found and treated initially by Serala Animal Clinic. Has lasting brain damage, right side of her body has a delay. Cognitively sound. Integrated into troop Aug 2022 with foster-mum Litchie. Additional chip 26817.', ''),
    ('Unalii', 'male', '', 'James', 2024, array['https://i.ibb.co/2YvYtBJ/blank-image-min.jpg']::text[], 'Arrived as an orphan.', ''),
    ('Zoro', 'male', '21468', 'Goliath', 2016, array['https://i.ibb.co/7QF57jD/Zoro-Goliath-Feb-2024-min.webp']::text[], 'Arrived as an orphan. Fostered by Mrs Gold.', 'Big round eyes, very fluffy especially around the head.'),
    ('Foxy', 'female', '21575', 'Goliath', 2018, array['https://i.ibb.co/j5NbM0z/Foxy-Goliath-Mar-2023-2-min.webp']::text[], 'Arrived an orphan. Mother was hit and killed by a car. Fostered by Mrs Gold. History of regularly juming in and out of enclosure.', 'Flashes above eyes and some silhouettes below as well, nervous of people, will eyebrow and head-bob if stared at.'),
    ('Grover', 'male', '26627', 'Goliath', 2022, array['https://i.ibb.co/nzWnzQX/Grover-Golith-21-02-2024-1-min.webp']::text[], 'Arrived as an orphan from Johannesburg wildlife vet along with Sophie. Mother was shot. Fostered by Mrs Gold and then by Dad & Bliss once in troop.', 'Round head, straight brow'),
    ('Sophie', 'female', '26623', 'Goliath', 2022, array['https://i.ibb.co/zfR3Bkn/Sophie-Goliath-Apr-2024-min.webp', 'https://i.ibb.co/GHdz2CK/Sophie-Goliath-April-24-min.webp', 'https://i.ibb.co/nDMdkPp/Sophie-Goliath-Aug-23-5-min.webp']::text[], 'Arrived as an orphan from Johannesburg wildlife vet along with Grover. Mother was shot. Fostered by Mrs Gold and then by Dad & Bliss once in troop.', 'Grumpy expression, M-shaped brow with peak on the middle, pale silhouettes around eyes'),
    ('Amy', 'female', '1223', 'Goliath', 2013, array['https://i.ibb.co/RBKvNs2/Amy-Goliath-Sept-2023-min.webp']::text[], 'Arrived as an orphan. Found alone on a game reserve.', 'Quite small, very pointy face'),
    ('Angelica', 'female', '1218', 'Goliath', 2008, array['https://i.ibb.co/xh0qtcC/Angelica-Goliath-Apr-2023-min.webp']::text[], 'Born in troop to Camilla (deceased). Has misaligned jaw, reason unknown but most likely genetic.', 'Distinctive misaligned jaw, short tail missing black tip, very light-grey scruffy coat'),
    ('Aurora', 'female', '26789', 'Goliath', 2020, array['https://i.ibb.co/sHK226G/Aurora-Goliath-Apr-2023-2-min.webp']::text[], 'Arrived as an orphan. Was found being sold on the side of the road for R100.', ''),
    ('Bliss', 'female', '1461', 'Goliath', 2010, array['https://i.ibb.co/SN920vm/Bliss-Goliath-Apr-2023-2-min.webp']::text[], 'Born in troop to Schlinkey.', 'Grumpy face, tail bent is various parts, missing black tip, looks quite similar to her sister Dad.'),
    ('Boetie', 'male', '1013', 'Goliath', 2013, array['https://i.ibb.co/qM5XdHp/boetie-goliath-mar2023-min.webp']::text[], 'Arrived as an adult. Found along and kept as a pet for month before handing in.', 'Smaller adult male, light golden coat'),
    ('Boetie Boy', 'male', '', 'Goliath', null::integer, array['https://i.ibb.co/2YvYtBJ/blank-image-min.jpg']::text[], 'Arrived as a juvenile ex-pet', ''),
    ('Claudette Marie', 'female', '26656', 'Goliath', 2021, array['https://i.ibb.co/S0wwdLM/Claudette-Marie-Goliath-Apr-2023-3-min.webp']::text[], 'Arrived as an orphan. Mother was shot and she she arrived with a wound on her arm. Fostered by Mrs Gold, also spent some time with Maggie Mae.', 'Tail amputated halfway due to injury sustained during integration, light-coloured coat and face'),
    ('Dana', 'female', '1467', 'Goliath', 2016, array['https://i.ibb.co/QpD7xCc/Dana-Goliath-Apr-2023-min.webp']::text[], 'Arrived as an orphan, collected from Levubu. Fostered by Shortie (now deceased).', 'Borad flat nose, straight brow, can be difficult to find'),
    ('DD', 'female', '98268', 'Goliath', 2017, array['https://i.ibb.co/T0SKYdJ/DD-Goliath-Apr-2023-min.webp']::text[], 'Arrived as an orphan. Was found alone in the bathroom of a restaurant. Fostered by Mrs Gold.', 'Very cute square face, round eyes, distinctive peak in middle of brow, usually with the alpha-group'),
    ('Digit', 'female', '1283', 'Goliath', 2014, array['https://i.ibb.co/Cz1tWsD/digit-goliath-feb2024-min.webp']::text[], 'Arrived as an orphan. Found stuck on a fence. Doesn’t like the introcage but is good with babies once they join the troop.', 'Long gently curved brow, very stocky, blad patch left side of head to due arrival injury'),
    ('Edson', 'male', '26769', 'Goliath', 2021, array['https://i.ibb.co/NmBMGHH/edson-goliath-may2024-min.webp']::text[], 'Arrived as an orphan. Found alone on a nature reserve. Fostered by Mrs Gold and then taken by Yma when in troop.', 'Dark face, big pointy ears, very neat trim golden coat'),
    ('Elio', 'male', '26543', 'Goliath', 2020, array['https://i.ibb.co/Nmvtdtd/elio-goliath-apr2024-min.webp']::text[], 'Born out of season in June 2021 and arrived as an orphan in July. Found alone on the side of a road. Fostered by Maggie Mae.', 'Slight silhouettes with lines under eyes, flared nostrils, looks simialr to Fritz but smaller and not as golden.'),
    ('Ellie', 'female', '26782', 'Goliath', 2019, array['https://i.ibb.co/RjMqP8q/ellie-goliath-april2023-min.webp']::text[], 'Arrived as an orphan. Found along on a game reserve, mother thought to have been killed by an eagle. Fostered by Mrs Gold. First time as a foster-mum in 2023/24, fostering Nugget.', 'Distinctive big sticky-out ears, quite slender, light-grey scruffy coat'),
    ('Fritz', 'male', '26718', 'Goliath', 2020, array['https://i.ibb.co/34D6ct5/fritz-goliath-mar2024-min.webp']::text[], 'Arrived as an orphan. Found alone in a tool shed on a farm.', 'Wavy brow, nervous of people and will eyebrow when stared at'),
    ('Gandalf', 'male', '1231', 'Goliath', 2014, array['https://i.ibb.co/ScG0gFz/gandalf-goliath-mar2022-min.webp', 'https://i.ibb.co/Wfq924d/gandalf-goliath-may2023-min.webp']::text[], 'Arrived as an orphan. Fostered by Halo (deceased).', 'Narrow triangular-shaped dark face, parting on head, tail tip damaged due to injury'),
    ('Jerusalem', 'female', '19915', 'Goliath', 2017, array['https://i.ibb.co/f09p0J1/Jerusalem-Goliath-Apr-2023-min.webp']::text[], 'Arrived as an orphan. Mother was hit and killed by a car with Jerusalem suffering a broken foot. Fostered by Mrs Gold. Featured as the star of “The Dodo: Comeback Kids” video iw', 'Flat nose, small peak in middle of brow, quite fluffy'),
    ('Keegie', 'female', '1439', 'Goliath', 2014, array['https://i.ibb.co/XWnQx6K/Keegie-Goliath-May-2023-min.webp']::text[], 'Arrived as an orphan. Fostered by Dad.', 'Floppy left ear due to Waffles sucking on it when babies, high-ranked, usually with alpha-group'),
    ('Kimbo', 'male', '1411', 'Goliath', 2009, array['https://i.ibb.co/rHsQgfz/Kimbo-Goliath-Apr-2023-2-min.webp']::text[], 'Born in troop to Camilla (deceased). High-ranked.', 'Stocky fluffy adult, white lines under eyes, curved uneven brow, kink on tail'),
    ('Korigan', 'male', '20044', 'Goliath', 2015, array['https://i.ibb.co/cg6grV8/korigan-goliath-apr2023-min.webp']::text[], 'Arrived as an orphan. Fostered by Mrs Gold, taken by alpha-group once in troop.', 'Big, pointy ears, strong broad muzzle, slightly golden coat'),
    ('Lottie', 'female', '26729', 'Goliath', 2021, array['https://i.ibb.co/GRcpDRY/lottie-goliath-apr2024-min.webp']::text[], 'Arrived as an orphan. Was found alone with mother under a caravan. Mother was possibly bitten by a snake and had passed away overnight. Fostered by Mrs Gold.', 'Distinctive patchy silhouettes around eyes, quite nervous of people'),
    ('Maddox', 'male', '26619', 'Goliath', 2019, array['https://i.ibb.co/Yhtxp6Z/maddox-goliath-apr2024-min.webp']::text[], 'Arrived as an orphan with several minor cuts. Treated for a cloudy left eye before entering troop. Fostered by Mrs Gold.', 'Slight white lines under eyes.'),
    ('Maggie Mae', 'female', '1612', 'Goliath', 2016, array['https://i.ibb.co/P4RMbZJ/maggie-mar-april-2023-min.webp']::text[], 'Arrived as an orphan, collected from SPCA. Fostered by Mrs Gold, but was quite independent. Had a venereal tumour removed in early 2022. Fostered Elio, and mother of Mary Sunshine who was born in troop.', ''),
    ('Mandy', 'female', '1905', 'Goliath', 2007, array['https://i.ibb.co/gmBV025/Mandy-Goliath-Apr-2023-min.webp']::text[], 'Born in troop to Sophia (deceased). Used to escape by climbing through the fence, but not recently.', 'Back arches down when walking, dark grey coat, tear on right ear'),
    ('Marja-Liisa', 'female', '26773', 'Goliath', 2020, array['https://i.ibb.co/fvfxJJF/marja-liisa-october-2023-min.webp']::text[], 'Arrived as an orphan. Mother was electrocuted on a pole.', 'No strong distinguishing features, quite slender and similar looking to Ellie.'),
    ('Max', 'male', '1674', 'Goliath', 2004, array['https://i.ibb.co/J5njyPQ/max-goliath-may2024-min.webp']::text[], 'Arrived in group at 8 months old and lived in enclosure since it was first built.', 'Very fluffy head, will readily headbob and eyebrow if looked at, small lump on base of scrotum'),
    ('Maysie', 'female', '21645', 'Goliath', 2018, array['https://i.ibb.co/9qx5S19/maysie-goliath-apr2024-min.webp']::text[], 'Arrived as an orphan. Was found alone on a golf course in Mokopane. Fostered by Mrs Gold. Has a history of jumping out of enclosure with Foxy.', 'Small and slender, small peak in brow, often with the babies'),
    ('Mirabelle', 'female', '21512', 'Goliath', 2015, array['https://i.ibb.co/0XWQ4g9/Mirabelle-Goliath-May-2023-2-min.webp']::text[], 'Arrived as an orphan with pneumonia. Fostered by Shortie (deceased).', 'Light-grey scruffy coat, distinctive patchy silhouettes around eyes, low ranked'),
    ('Mum', 'female', '1460', 'Goliath', 2009, array['https://i.ibb.co/V9GrGZW/Mum-Goliath-May-2023-min.webp']::text[], 'Born in troop to alpha-female Hartley (deceased). Fostered Tarzan.', 'Very fluffy around the face, grumpy expression'),
    ('Nollie', 'male', '1257', 'Goliath', 2014, array['https://i.ibb.co/7khBwy9/Nollie-Goliath-June-2023-min.webp']::text[], 'Arrived as an orphan.', 'Large male, low curved brow, dark, face, slight overbite and often holds lips slightly open.'),
    ('Pepsi', 'female', '1682', 'Goliath', 2007, array['https://i.ibb.co/7NCfFtV/Pepsi-Goliath-Apr-2023-min.webp']::text[], 'Born in troop to Schlinky', 'Left wrist bends to the side due to old break, confident with people and will follow along at fence line,'),
    ('Piglet', 'female', '1230', 'Goliath', 2014, array['https://i.ibb.co/1zxPspz/piglet-goliath-feb2024-min.webp']::text[], 'Arrived as an orphan.', 'Fluffy flat head, square ears, very cute looking'),
    ('Pippin', 'male', '1281', 'Goliath', 2014, array['https://i.ibb.co/nDfj9Yv/Pippin-Goliath-Apr-2023-min.webp']::text[], 'Alpha-male. Arrived as an orphan. Fostered by Schlinky.', 'Large adult, very broad flat face'),
    ('Schlinkey', 'female', '1906', 'Goliath', 2004, array['https://i.ibb.co/vs48X1r/schlinkey-goliath-setp2021-min.webp']::text[], 'Arrived in a group at 8 months old, was abused. Mother of Pepsi, Dad, Bliss. Fostered Pippin.', 'Large stocky adult, small tear top of right ear, thick tail which is missing the black tip'),
    ('Smoky', 'male', '1452', 'Goliath', 2014, array['https://i.ibb.co/BspshkQ/Smoky-Goliath-May-2023-min.webp']::text[], 'Arrived as an orphan. Found with someone in a bar.', 'Long, dark face with light silhouettes underneath, missing tip of tail due to injury, golden caot'),
    ('Tumbles', 'female', '31075', 'Goliath', 2013, array['https://i.ibb.co/YQ5Pv1h/Tumbles-Goliath-Apr-2023-2-min.webp']::text[], 'Arrived as an orphan. Was found alone and injured in Zimbabwe.', 'Triangular and pointy ears, thin silhouettes around eyes, slender, golden coat, will eyebrow is stared at.'),
    ('Vincent', 'male', '1431', 'Goliath', 2009, array['https://i.ibb.co/sw1YBKC/Vincent-Goliath-May-2023-min.webp']::text[], 'Born in troop to Mrs Gold. High-ranked.', 'Wavy brow, triangular cut on bottom of left ear.'),
    ('Waffles', 'female', '1273', 'Goliath', 2014, array['https://i.ibb.co/yyvVmGZ/Waffles-Goliath-Feb-2023-2-min.webp']::text[], 'Arrived as an orphan.', 'Quite a large adult, long nose, small tear on top of right ear, golden coat, kink near end of tail.'),
    ('Yma', 'female', '1264', 'Goliath', 2010, array['https://i.ibb.co/1z2StXt/yma-goliath-feb2023-min.webp']::text[], 'Born in troop to Sophia (now deceased). Fostered Amy and Edson once they joined the troop. High-ranked.', 'Flat crooked nose,fluffy head, tear on bottom of ht ear, kinks on tail.'),
    ('Nugget', 'male', '41186', 'Goliath', 2023, array['https://i.ibb.co/S0S16zY/nugget-goliath-mar2024-2.webp', 'https://i.ibb.co/VJ93TNJ/nugget-goliath-mar2024.webp']::text[], 'Arrived as an orphan in Dec 2023. Was confiscated by SPCA after being kept as a pet for at least 5 days and handed over to Beyond Borders Sanctuary in Tzaneen. History unknown. Fostered by Ellie.', ''),
    ('Mary Sunshine', 'female', '', 'Goliath', 2023, array['https://i.ibb.co/4WtwV3f/marysunshine-goliath-feb2024.webp', 'https://i.ibb.co/vsYkV8N/mary-sunshine-goliath-feb2024-min.webp']::text[], 'Born in troop Nov 2023 to Maggie Mae.', ''),
    ('Rowan', 'male', '41184', 'Goliath', 2023, array['https://i.ibb.co/VY6XQxC/rowan-goliath-mar2024.webp']::text[], 'Arrived as an orphan in Nov 2023. Found alone with head trauma, large swelling on back of head. Fostered by Mrs Gold.', ''),
    ('Wiz', 'female', '41220', 'Goliath', 2023, array['https://i.ibb.co/yFFHTJ4/wiz-goliath-apr2024-2.webp', 'https://i.ibb.co/fNyNQc9/wiz-goliath-apr2024.webp']::text[], 'Mother was Fluffy Witch, an elderly member of the Bandits, who passed away in Apr 2024 when Wiz was only 4 months old. Due to lack of bond with the other bandits, she was taken in as an orphan. Fostered by Mrs Gold.', ''),
    ('Nova', 'female', '', 'Goliath', 2024, array['https://i.ibb.co/2YvYtBJ/blank-image-min.jpg']::text[], 'Arrived as an orphan.', ''),
    ('Rudi', 'male', '', 'Goliath', 2024, array['https://i.ibb.co/2YvYtBJ/blank-image-min.jpg']::text[], 'Arrived as an orphan.', ''),
    ('Libe', 'female', '', 'Goliath', 2025, array['https://i.ibb.co/2YvYtBJ/blank-image-min.jpg']::text[], 'Born in troop to Maysie.', ''),
    ('Rune', 'male', '', 'Goliath', 2025, array['https://i.ibb.co/2YvYtBJ/blank-image-min.jpg']::text[], 'Arrived as an orphan.', ''),
    ('Hocus', 'female', '1615', 'H&B', 2003, array['https://i.ibb.co/w4pqxwc/hocus-hb-may2022-min.webp']::text[], 'Alpha-female. Approx DoB as unknown, min 2003. Mother of Millie and Luxi (deceased). Used to live in a Skunkey introcage with Millie, Luxi, Priscilla, Percy, Yoshi & Apollo, who all became the starting group of H&B in 2015. Not used as a foster-mum but very good with babies once they’re in the troop.', 'Large and stocky, serious expression, usually with Millie and juveniles'),
    ('Jaintjie', 'female', '', 'H&B', 2003, array['https://i.ibb.co/CbdGvSp/jaintjie-hb-jul2024-min.webp']::text[], 'Arrived as an orphan, mother was hit & killed by a car. Lived for a long time in Skunkey introcages with Count and Harmony. Moved to H&B in 2022 and integrated into troop July 2024.', 'Humanised and very talkative, flashes above eyes.'),
    ('Jinx', 'male', '1593', 'H&B', 2007, array['https://i.ibb.co/GCcS5Yt/jinx-hb-apr2023-min.webp']::text[], 'Previously lived in a Skunkey introcage with Snow White and Thandi before being moved to H&B. Integrated in Sept 2020. Low ranked.', 'Round eyes with dark pink silhouettes, Long straight nose, surprised expression, usually found at back of enclosure.'),
    ('Skylar', 'female', '1214', 'H&B', 2009, array['https://i.ibb.co/sHL17VN/skylar-hb-may2023-min.webp']::text[], 'Born 2009 to Suvanna (deceased). Previously lived in a group at Robert C and was moved to H&B when the others passed away. Integrated in July 2021. Low ranked. Fostered Herbert, Wanda, and Bluebell.', 'Large adult, low brow, high forehead, grumpy expression, holds tail up very often.'),
    ('Mofassa', 'male', '1875', 'H&B', 2003, array['https://i.ibb.co/sqGjD5B/mofassa-hb-apr-2024-min.webp']::text[], 'Approx DoB as unknown. Arrived in 2004. Lived in a Robert introcage for a long time before being moved to H&B. Integrated in August 2023. High-ranked.', 'Strong adult with broad shoulder, short tail missing black tip, broken middle finger on right hand, very protective of the babies.'),
    ('Mara', 'female', '26811', 'H&B', 2022, array['https://i.ibb.co/rFTKV7j/mara-hb-apr2024-min.webp']::text[], 'Arrived as an orphan. Was found alone on roadside near Polokwane. Fostered by Millie. Very good with the new babies, potential foster-mum herself!', 'Stocky with wide face, usually with the alpha-group'),
    ('Apollo', 'male', '1076', 'H&B', 2005, array['https://i.ibb.co/k3CPBc3/apollo-hb-june2022-min.webp']::text[], 'Previously lived in a Skunkey introcage with Hocus, Millie, Luxi (deceased), Priscilla, Percy, and Yoshi, who all became the starting group of H&B in 2015.', 'Smallish adult but stocky, white lines and spots below eyes, curved brow, end of tail very thin.'),
    ('Millie', 'female', '1240', 'H&B', 2007, array['https://i.ibb.co/nb1pkqk/millie-hb-may2023-min.webp']::text[], 'Born Dec 2007 on site to Hocus. Sister of Luxi (deceased). Used to live in a Skunkey introcage with Hocus, Millie, Priscilla, Percy, Yoshi & Apollo, who all became the starting group of H&B in 2015. Very good with babies! Fostered Mara, Tufty, Paulie, and Mikey, carrying all of the last three out into troop herself!', 'Very narrow face, patchy silhouettes with flashes above eyes, broken middle finger on left hand, small mark on left cheek.'),
    ('Victoria', 'female', '1306', 'H&B', 2000, array['https://i.ibb.co/M6ynw4b/victoria-hb-may2022-min.webp']::text[], 'Born approx 2000, history unknown. Used to be in Lankora (then SAAV) troop, but escaped and became bandit. Was then trapped and moved to a Skunkey introcage before being moved to H&B. Integrated separately but at the same time as the starting group in 2015.', 'Small geriatric female, scruffy light-coloured coat, walks slowly with an arched back, tail tip damaged due to bush fire in Lankora (then SAAV) in 2008, sometimes reaches up as if she''s going to touch the electric fence.'),
    ('Herbert', 'male', '26745', 'H&B', 2022, array['https://i.ibb.co/f9GfHrY/herbert-hb-apr2024-min.webp']::text[], 'Arrived as an orphan. Mother was killed by a car. Fostered by Skylar.', 'Hard pink silhouettes around eyes and mouth, light grey coat.'),
    ('Harmony', 'female', '1672', 'H&B', 2003, array['https://i.ibb.co/GtWbM0g/harmony-hb-may2022-min.webp']::text[], 'Arrived as an orphan, mother was shot by a farmer. Previously lived in a Skunkey introcage with Bill, Jaintjie and Count. Integrated Oct 2019. Very good natured, loves the babies. Fostered Thigpen.', 'Very distinctive golden-brown coat, round head with ears sticking out, curved brow with ''sad'' expression, pale wrinkly silhouettes around eyes, hands point out while walking/standing.'),
    ('Snow White', 'female', '1646', 'H&B', 2003, array['https://i.ibb.co/SQcN4HY/snow-white-hb-apr2023-min.webp']::text[], 'Previously lived in a Skunkey introcage with Thandi and Jinx. Integrated in December 2019.', 'Small female, thin face with white mark on left cheek, silhouettes above and below eyes, slightly wavy brow.'),
    ('Yoshi', 'male', '1426', 'H&B', 2006, array['https://i.ibb.co/zXZ9Zw0/yoshi-hb-may2022-min.webp']::text[], 'Alpha-male. Born 2006 on site to Priscilla. Used to live in a Skunkey introcage with Hocus, Millie, Luxi (deceased), Priscilla, Percy, and Apollo, who all became the starting group of H&B in 2015.', 'Large adult, very long bushy tail with tick black tip, low bushy brow.'),
    ('Priscilla', 'female', '1607', 'H&B', 2003, array['https://i.ibb.co/ygbnB3j/priscilla-hb-feb2022-min.webp']::text[], 'DoB unknown, min 2003. Mother of Percy and Yoshi. Previously lived in a Skunkey introcage with Hocus, Luxi, Millie, Percy, Yoshi & Apollo, who were the starting group of H&B in 2015.', 'Plucked brow in middle, white moustache, stock body, patch of hair sticking up on left hip, kink in tail.'),
    ('Fudge', 'male', '26794', 'H&B', 2022, array['https://i.ibb.co/HTwQRBr/fudge-hb-may2024-min.webp']::text[], 'Arrived as an orphan, reason unknown. Fostered by Percy as the first ever orphan introduced to H&B troop!', 'Thin and scruffy, small traiangular face, light golden coat.'),
    ('Pedro', 'male', '1948', 'H&B', 2005, array['https://i.ibb.co/tY8Fk2D/pedro-hb-jun2024-min.webp']::text[], 'Arrived as a newborn orphan. Used to live in a Skunkey introcage with Jasmine and Jezabel before being moved to H&B. Integrated in Sept 2019.', 'Thin and often scruffy, large tear on left ear, broken middle finger on left hand, often follows people and cars along the fence.'),
    ('Thigpen', 'male', '26744', 'H&B', 2022, array['https://i.ibb.co/16n6PJw/Thigpen-hb-may2024-min.webp']::text[], 'Arrived as an orphan. Was found alone at a stable. Quite wobbly on arrival. Integrated with Herbert & fostered by Harmony.', 'Golden coat, dark narrow face with pointy chin, slighty peak in brow'),
    ('Wanda', 'female', '41188', 'H&B', 2023, array['https://i.ibb.co/h7BJ648/wanda-hb-mar2024.webp']::text[], 'Arrived as an orphan in Dec 2023. Started foster-mum integration at Goliath but didn''t bond with mums and was moved to H&B with Bluebell. Fostered by Skylar.', 'Very fluffy, pink around eyes and mouth, confident with people, usually near Bluebell.'),
    ('Paulie', 'male', '41189', 'H&B', 2023, array['https://i.ibb.co/s3644St/paulie-hb-mar2024-2.webp', 'https://i.ibb.co/CtH3Gjt/paulie-hb-mar2024.webp']::text[], 'Arrived as an orphan in Nov 2023. Was found alone, wet and shivering, at a storage shed at Magoesbaskloof Adventures. History unknown. Arrived with 5-6 ticks, crusty/muddy face and bruised left eye. Very close bond with Mikey. Fostered by Millie.', 'Dark face, big pointy ears, big eyes close together, trim hair on head.'),
    ('Kathleen', 'female', '41183', 'H&B', 2023, array['https://i.ibb.co/K7Jqcdw/kathleen-hb-feb2024.webp', 'https://i.ibb.co/FY4QZjX/kathleen-hb-mar2024-2.webp']::text[], 'Arrived as an orphan in Nov 2023. Was found alone in a tree following a troop fight in a nature reserve near Gravelot. Said to have been there all day screaming, troop did not return so was taken in and handed over. Fostered by Percy.', 'Quite big, lots of pink on face, looks like she has freckles.'),
    ('Tufty', 'female', '41182', 'H&B', 2023, array['https://i.ibb.co/MBTX88Q/tufty-hb-apr2024.webp', 'https://i.ibb.co/8myqv4z/tufyt-hb-feb2024.webp']::text[], 'Arrived as an orphan in Nov 2023. Mother was killed by a snare. Vry comfortable with people on arrival so she was likely kept as a pet for while. Fostered by Millie.', 'Similar to Mikey, pink around face.'),
    ('Bluebell', 'female', '41187', 'H&B', 2023, array['https://i.ibb.co/YWpbwsx/bluebell-hb-mar2024.webp']::text[], 'Arrived as an orphan in Dec 2023 at approx 10 weeks old. Started foster-mum integration at Goliath but didn''t bond with mums and was moved to H&B with Wanda. Fostered by Skylar.', 'Darkish face, sleepy expression, very fluffy, usually near Wanda.'),
    ('Brigitte', 'female', '', 'H&B', 2024, array['https://i.ibb.co/2YvYtBJ/blank-image-min.jpg']::text[], 'Arrived as an orphan.', ''),
    ('Miri', 'female', '', 'H&B', 2024, array['https://i.ibb.co/2YvYtBJ/blank-image-min.jpg']::text[], 'Arrived as an orphan.', ''),
    ('Sarah', 'female', '', 'H&B', 2024, array['https://i.ibb.co/2YvYtBJ/blank-image-min.jpg']::text[], 'Arrived as an orphan.', ''),
    ('Agatha', 'female', '', 'H&B', 2024, array['https://i.ibb.co/2YvYtBJ/blank-image-min.jpg']::text[], 'Arrived as an orphan.', ''),
    ('Keith Mann', 'male', '', 'H&B', 2025, array['https://i.ibb.co/2YvYtBJ/blank-image-min.jpg']::text[], 'Arrived as an orphan.', ''),
    ('Wendell', 'male', '', 'H&B', 2025, array['https://i.ibb.co/2YvYtBJ/blank-image-min.jpg']::text[], 'Arrived as an orphan.', ''),
    ('Salty', 'male', '', 'H&B', 2025, array['https://i.ibb.co/2YvYtBJ/blank-image-min.jpg']::text[], 'Arrived as an orphan.', ''),
    ('Trixi', 'female', '41218', 'Lankora', 2023, array['https://i.ibb.co/km6kBvC/trixi-saav-apr2024-min.webp']::text[], 'Arrived as an orphan in Mar 2024.Was found on deceased mother''s body by workers on a farm, cold and dehydrated. Kept my owners wife for four days prior to arrival at VMF. Fostered by Acorn, but mostly with Dabney in troop.', ''),
    ('Harris', 'male', '41219', 'Koko', 2023, array['https://i.ibb.co/82Nps57/harris-saav-apr2024-min.webp']::text[], 'Arrived as an orphan in Mar 2024. History unknown, but was kept as a pet for at least 2 months. Fostered by Acorn.', ''),
    ('Berlioz', 'male', '1819', 'Lankora', 2008, array['https://i.ibb.co/XJnXRWS/berlioz-saav-may2023-min.webp']::text[], 'Nothing. Nada. Zilch.', 'Lower left canine sticks out, curved brow.'),
    ('Delilah', 'female', '1266', 'Lankora', 2010, array['https://i.ibb.co/HdrQZwM/deliliah-saav-apr2024-min.webp']::text[], 'Alpha-female. Born in troop to Survivor (deceased).', 'Distinctive white moustache, flashes above eyes,, light silhouettes underneath, nervous of people, will eyebrow if looked at.'),
    ('Nora', 'female', '19981', 'Lankora', 2017, array['https://i.ibb.co/BKL0Gkd/nora-saav-apr2024-min.webp']::text[], 'Arrived as an orphan, story unknown. Fostered by Hollie. Regularly jumps in & out of enclosure.', 'Distinctive golden coat, light silhouettes around eyes, ‘angry’ brow.'),
    ('Scooter', 'male', '31918', 'Lankora', 2006, array['https://i.ibb.co/M26Cs51/scooter-saav-may2023-min.webp']::text[], 'Alpha-male. Humanised and can be aggressive towards people.', 'Distinctive parting on head, kink near end of tail, will eyebrow if stared at.'),
    ('Shemesh', 'male', '20045', 'Lankora', 2017, array['https://i.ibb.co/NTDGKHW/shemesh-saav-apr2024-min.webp']::text[], 'Arrived as an orphan. Was found alone in Tzaneen.', 'Large with slightly golden coat, long narrow nose.'),
    ('Dora', 'female', '26767', 'Lankora', 2020, array['https://i.ibb.co/fGpM7V0/Dora-saav-oct2023-min.webp']::text[], 'Arrived as an orphan. Arrived with a broken arm that had already begun to heal. Story unclear. Fostered by Hollie (deceased).', 'Thin silhouettes around eyes, low brow giving a grumpy/angry expression.'),
    ('Ulku', 'female', '26793', 'Lankora', 2020, array['https://i.ibb.co/p3w2z3D/ulku-saav-apr2024-min.webp']::text[], 'Arrived as an orphan. Mother was shot. Fostered by Buttercup (deceased).', 'Light golden coat, thick bushy brow, fluffy white hair around head.'),
    ('Utku', 'male', '26720', 'Lankora', 2022, array['https://i.ibb.co/wSZggYR/utku-saav-apr2024-min.webp']::text[], 'Arrived as an orphan. Was found clinging to his dead mother is Mussini. Fostered by Acorn but went into troop by himself.', 'Often sucking his fingers'),
    ('Phoebe', 'female', '26719', 'Lankora', 2022, array['https://i.ibb.co/4fLvnK9/phoebe-saav-mar2024-min.webp']::text[], 'Arrived as an orphan. Reason is unclear, apparently walked into a man’s house all by herself and started hugging him, which is likely not the entire story. Fostered by Acorn.', ''),
    ('Apie', 'female', '1550', 'Global', 2007, array['https://i.ibb.co/Bf0LXDj/apie-global-feb2023-min.jpg']::text[], 'Arrived as a juvenile. Has lived in both James and Global enclosures. Good foster-mum, fostered Pascall and Toni.', 'Large boxy foreahead, low brow, walks with elbows bent.'),
    ('Ayla', 'female', '1486', 'Global', 2011, array['https://i.ibb.co/TMCLmLN/ayla-global-june2023-min.jpg']::text[], 'Arrived as an orphan. Was found and brought into a house by dogs. Fostered by former alpha-female Pippa (deceased).', 'Flashes above eyes, pink patches around brow and chin, aggressive and eyebrows a lot'),
    ('Chicken', 'female', '1254', 'Global', 2013, array['https://i.ibb.co/ccxZHKC/chicken-global-mar2024-min.jpg']::text[], 'Arrived as an orphan Apr 2021. Mother was hit and killed by a car, Totsy was kept as a pet. Fostered by Missie. Fostered Dumbo.', 'Disintive white dots under both eyes, very lean and slender, aggressive and eyebrows a lot, will approach the fence.'),
    ('Kofi', 'female', '1455', 'Global', 2016, array['https://i.ibb.co/bFyk2Yx/kofi-global-may2022-min.jpg']::text[], 'Arrived as an orphan Nov 2016. Was dropped off another rescue center in Hoedspruit. Fostered Danny and Anya.', 'White moustache, think silhouettes around eyes, pointy ears, square head, fluffy around the face.'),
    ('Rahni', 'female', '9924', 'Global', 2016, array['https://i.ibb.co/mHt37DL/rahni-global-sept2023-min.jpg']::text[], 'Arrived as an orphan Nov 2016. Mother was hit and killed by a car. Very high-ranked.', 'Distinctive v-shaped brow, bald spot middle/top of forehead, triangular face.'),
    ('Dumbo', 'male', '21498', 'Global', 2017, array['https://i.ibb.co/gy7ZQ1r/dumbo-global-may2022-min.jpg']::text[], 'Arrived as an orphan Apr 2018. Mother was hit and killed by a car. Fostered by Chicken.', 'Big sticky-out ears, partial parting on head, golden-brown coat, tall and slender'),
    ('Meghan', 'female', '21507', 'Global', 2017, array['https://i.ibb.co/94cJYvb/meghan-global-may2022-min.jpg']::text[], 'Arrived as an orphan May 2018. Fostered by Missie. Foster-mum of Eamon.', 'Tear on top of left ear, often with Abby, eyebrows a lot.'),
    ('Tesha', 'female', '19871', 'Global', 2017, array['https://i.ibb.co/VY8MNYd/tesha-global-feb2023-min.jpg']::text[], 'Arrived as an orphan Aug 2018. Was found alone behind a fridge at a game lodge.', 'Very round teddy bear face, curved back, broken middle finger on one hand, banded tail – not fully black, keeps to herself and usually on the Lankora-side of enclosure.'),
    ('Abby', 'female', '21513', 'Global', 2018, array['https://i.ibb.co/VQbGM34/abby-global-sept2023-min.jpg']::text[], 'Arrived as an orphan Jan 2019. Was found alone on a farm.', 'Eyes are very round and close together, rounded brow, fluffy head'),
    ('Martini', 'female', '26761', 'Global', 2019, array['https://i.ibb.co/dc99fmX/martini-global-feb2024-min.jpg']::text[], 'Arrived as an orphan Dec 2019. Mother was hit by a car and ran away without her. Fostered by Dolly. High ranked.', 'Thin and slender, triangular head, big sticky-out ears, yellow coat.'),
    ('Hugo', 'male', '26602', 'Global', 2020, array['https://i.ibb.co/XLNHrFR/hugo-global-sept2023-min.jpg']::text[], 'Arrived as an injured juvenile May 2022. Was found in someone’s garden in Tzaneen. Vet confirmed two pellets in head and a broken hip. Has lasting brain damage right arm hangs a little, right leg drags slightly. Integrated Oct 2022.', 'Golden coat, pale silhouettes around eyes, big stickyu-out ears high on head.'),
    ('Pascall', 'male', '26723', 'Global', 2020, array['https://i.ibb.co/s9w00SM/pascall-global-feb2024-min.jpg']::text[], 'Arrived as an orphan Nov 2020. Mother was stoned to death, he arrived extremely traumatized, lots of self-inflicted scratch marks on face. Fostered by Apie.', 'Dark hooked ears, white lines under eyes, dark face.'),
    ('Eamon', 'male', '26694', 'Global', 2021, array['https://i.ibb.co/rFdbn3g/eamon-global-sept2023-min.jpg']::text[], 'Arrived as an orphan Jan 2022. Found alone and dehydrated. Fostered by Meghan.', 'Big eyes, small mouth/chin, low fluffy brow, angry looking'),
    ('Mini Max', 'male', '26666', 'Global', 2021, array['https://i.ibb.co/47mNWTx/mini-max-global-mar2024-min.jpg']::text[], 'Arrived as an orphan Oct 2021 with a broken left leg. Reason unknown. Still has a pin in his leg. Fostered by Dolly.', 'Golden coat, larger than Eamon, pointy ears, triangular shaped face'),
    ('Terri', 'female', '26643', 'Global', 2021, array['https://i.ibb.co/YkkJnYm/terri-global-may2024-min.jpg']::text[], 'Arrived as an orphan Nov 2021. Was found being sold at the side of a road in Mozambique. Initially integrated into Koko but was pulled out almost immediately due to weakness in legs. Suffered from compressed spine most likely caused by an unknown fall. Reintegrated into Global after recovering due to lack of bonding at Koko. Fostered by Missie. Still has some weakness so walks and sits weirdly.', 'Light-grey coat, patchy pink chin, trim coat, feet point inwards.'),
    ('Anya', 'female', '26698', 'Global', 2022, array['https://i.ibb.co/qB3KkPH/anya-global-feb2024-min.jpg']::text[], 'Arrived as an orphan Nov 2022, only a few days old. Mother was killed by dogs, witness called us straight away. Struggled with a bacterial infection in baby care, very small as a result. Fostered by Kofi.', 'Tiny, angry brow, flashes above eyes.'),
    ('Danny', 'male', '26743', 'Global', 2022, array['https://i.ibb.co/LgR5ZWD/danny-global-may2024-min.jpg']::text[], 'Arrived as an orphan Nov 2022. Found alone by some church workers and handed over to Serala Animal Clinic. Fostered by Kofi.', 'Fluffy, big ears, sucks his hand a lot.'),
    ('Lyyti', 'female', '41178', 'Global', 2023, array['https://i.ibb.co/J35734k/lyyti-global-feb2024.jpg']::text[], 'Arrived as an orphan in Nov 2024. Was found on a veranda in Haenertsburg alone and crying for at least 12 hours. Scabby face on arrival. Fostered by Meghan.', ''),
    ('June', 'female', '41196', 'Global', 2023, array['https://i.ibb.co/7jcS8Fp/june-global-mar2024-2.jpg']::text[], 'Arrived as an orphan in Nov 2023. Was being sold to a vet in Louis Trichardt who then called us. Fostered by Meghan.', ''),
    ('Adam', 'male', '', 'Global', 2024, array['https://i.ibb.co/2YvYtBJ/blank-image-min.jpg']::text[], 'Arrived as an orphan.', ''),
    ('Donald', 'male', '', 'Global', 2024, array['https://i.ibb.co/2YvYtBJ/blank-image-min.jpg']::text[], 'Arrived as an orphan.', ''),
    ('Mema', 'female', '', 'Global', 2025, array['https://i.ibb.co/2YvYtBJ/blank-image-min.jpg']::text[], 'Arrived as an orphan.', ''),
    ('Lili', 'female', '26591', 'Jalamango', 2021, array['https://i.ibb.co/5x0tXBh/lili-jalamango-may2024.webp']::text[], 'Arrived as an orphan. Was found clinging to dead mother by roadside close of Haenertsburg. Fostered by Zea.', 'Very dark coat with black arms (similar colouration to Zea), curved brow giving her a cute sad expression, much more fluffy than Nino and smaller than the others.'),
    ('Mango', 'male', '19942', 'Jalamango', 2015, array['https://i.ibb.co/yXPQ7qX/mango-jalamango-may2024.jpg']::text[], 'VMF’s first samango orphan. Was integrated with adult-male Sammy (deceased) in the old samango enclosure in sickbay section. He was moved to the new Jalamango enclosure in 2018 with Jesse (deceased) and Zea. Humanised and doesn’t like people very much.', 'Only adult male and by far the largest monkey in the troop, humanised and will approach the fence, generally good-natured but will head-bob if he doesn’t like you.'),
    ('Nino', 'male', '26790', 'Jalamango', 2020, array['https://i.ibb.co/Cmp05WZ/nini-jalamango-may2024.webp']::text[], 'Arrived as an orphan. Was found being sold on the side of a road and confiscated by a game ranger.', 'Smallest in the troop despite being older than Lili, will head-bob and twist head when stared at, good-natured and playful.'),
    ('Satchmo', 'male', '26711', 'Jalamango', 2019, array['https://i.ibb.co/NtKFqv1/satchmo-jalamango-mar2024.webp']::text[], 'Arrived as an orphan Jan 2020. Collected from Chimp Eden after being found alone and handed in. Integrated in April 2020.', 'Orange colouration on lower back, otherwise looks very similar to Zayda, very playful and good-natured, slight hypertropia (misaligned) left eye'),
    ('Zayda', 'female', '26703', 'Jalamango', 2019, array['https://i.ibb.co/Dzfvp31/zayda-jalamango-aug2023.webp']::text[], 'Arrived as a juvenile Jan 2022. Was found as a baby alone by roadside in Lake Sabaya, suffering from possible concussion. Kept by a vet for a year due to health issues – vomiting, due to thickened gall bladder wall. Integrated Aug 2022. Has escaped enclosure multiple times.', 'Very similar looking to Satchmo, orange colouration on back not as pronounced.'),
    ('Zea', 'female', '21521', 'Jalamango', 2022, array['https://i.ibb.co/XSL2YxH/zea-jalamango-sep2023.webp']::text[], 'Arrived as a juvenile ex-pet, who had a broken arm. Was integrated with Mango and Jesse (deceased) in the old samango enclosure in sickbay section, before they were moved to the new Jalamango enclosure in 2018. Humanised and can be aggressive.', 'Only adult female, very dark coat, very straight brow which gives her a serious expression, humanised and will approach the fence.'),
    ('Casanova', 'female', '1146', 'Koko', 2010, array['https://i.ibb.co/CsBvBxd/casanova-koko-nov2023-min.webp']::text[], 'Born in troop to Kush (deceased)', 'Very distinctive thick and white moustache, scar on left eyebrow'),
    ('Long Arms', 'female', '', 'Koko', 2008, array['https://i.ibb.co/KKS3t4d/long-arms-koko-feb2022-min.webp']::text[], 'Mother of Elena-Ann', 'White moustache, more prominent on sides of mouth, right nipple pink, left nipple longer and black, looks similar to Jacob and somewhat similar to Mystery'),
    ('Schnitzel', 'female', '1222', 'Koko', 2008, array['https://i.ibb.co/MPwj1zJ/schnitzel-koko-feb2023-min.webp']::text[], 'Born in troop to Brownie', 'Distinctive golden coat, thick straight brow, pale rings around eyes, eyes close together'),
    ('Helmet', 'male', '1333', 'Koko', 2009, array['https://i.ibb.co/cg1xCwb/helmet-koko-dec2023-min.webp']::text[], 'Born in troop to Other', 'Smooth, helmet-shaped head with parting in the middle, very dark face, light-grey coat, brow not as low / angry looking as Smith'),
    ('Mystery', 'female', '1242', 'Koko', 2009, array['https://i.ibb.co/VMZT2BN/mystery-koko-may2023-min.webp']::text[], 'Born in troop to Other', 'Thin white and straight moustache on upper lip, kink / bend in middle of tail, straight brow'),
    ('Capie', 'male', '31153', 'Koko', 2010, array['https://i.ibb.co/8s1vg8g/capie-koko-may2022-min.webp']::text[], 'Born in troop to Koko (now deceased). Current alpha-male. 2nd chip 31209.', 'Distinctive ''Koko'' look – patchy silhouettes around eyes, moustache, & golden coat.'),
    ('Irene', 'female', '31897', 'Koko', 2010, array['https://i.ibb.co/mS68zsh/irene-koko-may2023-min.webp', 'https://i.ibb.co/KzyqT2R/irene-koko-nov2023-min.webp']::text[], 'Arrived as an orphan. Integrated in 2012 as a group along with Grace, Alec (both now in IC), Luka, TJ, and Laux. 2nd chip 31157.', 'Very low bushy flat brow, quite a flat head, nervous of people and rarely comes to the fence'),
    ('Jacob', 'female', '1244', 'Koko', 2010, array['https://i.ibb.co/b7xtMct/jacob-koko-nov2023-min.webp']::text[], 'Born in troop.', 'Dark face with flat nose, goofy expression, protruding muzzle, nervous of people'),
    ('Luka', 'female', '1191', 'Koko', 2010, array['https://i.ibb.co/c8DFs9y/luka-koko-apr2022-min.webp']::text[], 'Arrived as an orphan. Found by people out hunting. Integrated in 2012 as a group along with Grace, Alec (both now in IC), Irene, TJ, and Laux. Very good foster-mum.', 'Pointy ears, especially left ear, which is slightly hooked, tiny hole in right ear, pale silhouettes around eyes, peak in middle of brow, general untidy look'),
    ('Rosa', 'female', '1177', 'Koko', 2011, array['https://i.ibb.co/CwMTyyT/rosa-koko-nov2023-min.webp']::text[], 'Born in troop to Roman Nose (ex-alpha, now deceased).', 'Orange-brown eyes, blow plucked more prominent in the middle, very menacing expression'),
    ('Elena-Ann', 'female', '1337', 'Koko', 2013, array['https://i.ibb.co/VBJc35H/elena-ann-koko-nov2023-min.webp']::text[], 'Born in troop to Long Arms', 'Flat nose, white / grey fingers and toes, brow groomed / plucked in middle and slightly to the right, looks like her mum Long Arms but without the moustache, quiet and gentle female'),
    ('Kara', 'female', '1150', 'Koko', 2013, array['https://i.ibb.co/TckKRk3/kara-koko-apr2023-min.webp']::text[], 'Arrived as an orphan. Mother was killed by dogs on a farm in Agatha. Fostered by Curtis (jumped out and is now in Robert troop).', 'Very patchy hard white silhouettes around eyes, quite similar to Joli, flat face, often has an asymmetrical look in her eyes'),
    ('Patrick-Felis', 'male', '1345', 'Koko', 2013, array['https://i.ibb.co/QHTXbBB/patrick-felis-koko-dec2023-min.webp']::text[], 'Arrived as an orphan, mum was killed for bushmeat in Mozambique. Fostered by Koko (deceased).', 'Pink silhouettes around eyes, slight pink dots / tears under eyes, long black area on tail, tear on right ear, short coat'),
    ('Smith', 'male', '1331', 'Koko', 2013, array['https://i.ibb.co/Dz2Xdn0/smith-koko-apr2023-min.webp']::text[], 'Born in troop to Other', 'Very dark face with broad muzzle, low brow (angry look), similar looking to his mother Other, no black patches on scrotum, scar on left thigh'),
    ('Biscuit', 'male', '1336', 'Koko', 2014, array['https://i.ibb.co/xJpdVc4/biscuit-koko-may2023-min.webp']::text[], 'Born in troop to Brownie. High ranked.', 'Distinctive golden-brown coat, round eyes with full silhouettes, curved brow'),
    ('Vainilla', 'female', '1263', 'Koko', 2014, array['https://i.ibb.co/jb5MPxv/vainilla-koko-feb2023-min.webp']::text[], 'Born in troop to Zebedee.', 'Eyebrow plucked/groomed all the way across (thicker in the middle), dark face'),
    ('Mokey', 'female', '19708', 'Koko', 2015, array['https://i.ibb.co/PcNyrrj/mokey-koko-apr2024-min.webp']::text[], 'Arrived as an orphan, was found at a game reserve with possible mother deceased nearby. Fostered by Zebedee.', 'White dot/mark on bridge of nose, distinctive pink around both eyes, light-grey scruffy coat'),
    ('Joli', 'female', '20026', 'Koko', 2017, array['https://i.ibb.co/McdpP5G/joli-koko-may2023-min.webp']::text[], 'Newly established alpha-female. Arrived as an orphan, found at the side of the road. Fostered by Luka.', 'Pale silhouettes around eyes, similar to Kara but has more marks / lines above eyes, very patchy groomed parts of brow'),
    ('Panacur', 'female', '1112', 'Koko', null::integer, array['https://i.ibb.co/F4r3X3V/panacur-koko-may2022-min.webp']::text[], 'DOB unknown. Very good foster-mum. Fostered Peggy, Dobby, Dirkules, and Riccardo', 'Tear on bottom of left ear, pale silhouettes around eyes with dots/marks on eyelids (more obvious above her right eye)'),
    ('Peggy', 'female', '20050', 'Koko', 2017, array['https://i.ibb.co/pQKGwqq/peggy-koko-nov2023-min.webp']::text[], 'Arrived as an orphan, mother died after being caught on a fence. Fostered by Panacur.', 'White lines under eyes, very cute face, brow is bright and bushy'),
    ('Loustic', 'male', '19733', 'Koko', 2018, array['https://i.ibb.co/ypD4R2V/loustic-koko-dec2023-min.webp']::text[], 'Arrived as an orphan, mother was hit & killed by a car. Fostered by Luka.', 'Golden-brown coat, shiny part on bridge of nose, pale silhouettes around eyes'),
    ('Paloma', 'female', '19875', 'Koko', 2018, array['https://i.ibb.co/sgvGbB6/paloma-koko-oct2023-min.webp']::text[], 'Arrived as an orphan, was bitten by dogs. Fostered by Luka.', 'Grumpy expression, looks a little bit like Karla except larger and wider face, almond shaped silhouettes around eyes'),
    ('Yllena', 'female', '21561', 'Koko', 2018, array['https://i.ibb.co/2vKKvNT/yllena-koko-may2023-min.webp']::text[], 'Arrived as an orphan, found alone in Tzaneen. Fostered by Kara. Fostered Taro and Atlas.', 'Golden-brown coat, white tears / lines under eyes'),
    ('Karla', 'female', '26753', 'Koko', 2019, array['https://i.ibb.co/hXrk5kV/karla-koko-nov2023-min.webp']::text[], 'Arrived 2020 as an orphan. Fostered by Luka.', 'Dark face with broad mouth, confident and high ranked'),
    ('Ducat', 'male', '26652', 'Koko', 2020, array['https://i.ibb.co/59T65QL/ducat-koko-nov2023-min.webp']::text[], 'Arrived as an orphan. Fostered by Luka.', 'Low, gently curving brow, sad expression, almond-shaped eyes, round head, adult male size'),
    ('Yeliz', 'female', '26735', 'Koko', 2020, array['https://i.ibb.co/GCkWTNC/yeliz-koko-nov2023-min.webp']::text[], 'Arrived as an orphan, mother was shot and fell from a tree, Yeliz suffered minor head wounds. Fostered by Luka.', 'Big ‘sticky-out’ tears, distinctive tear on top of left ear, light-grey coat, white lines under eyes'),
    ('Oswald', 'male', '26655', 'Koko', 2021, array['https://i.ibb.co/txBkhX7/oswald-koko-nov2023-min.webp']::text[], 'Arrived as an orphan, was found alone in a tree in Louis Trichardt. Fostered by Luka.', 'Wispy, straight brow, larger than Seeti, less golden than Seeti'),
    ('Seeti', 'male', '26816', 'Koko', 2021, array['https://i.ibb.co/BcGTTJB/seeti-koko-nov2023-min.webp']::text[], 'Arrived as an orphan, found alone in a garden. Kept for 4 weeks before handing over. Fostered by Peggy.', 'Smaller than Oswald (more Taro side), slightly golden coat (see forehead)'),
    ('Taro', 'male', '26824', 'Koko', 2022, array['https://i.ibb.co/r2dMLXT/taro-koko-nov2023-min.webp']::text[], 'Fostered by Yllena', 'Only baby this year, eyebrow round on both sides'),
    ('Other Sub', 'female', '1290', 'Koko', 2008, array['https://i.ibb.co/cJhsf3f/other-sub-koko-mar2021-min.webp']::text[], 'Born 2008 in troop to other.', 'Curved nose profile (‘snub-nosed’), tall helmet-head with parting, two tears in middle of left ear, looks like Other but is much larger, has more distinctive parting on head and tail looks better'),
    ('Yoda', 'male', '41192', 'Koko', 2023, array['https://i.ibb.co/s1zM2FL/yoda-koko-feb2024-2.jpg']::text[], 'Arrived as an orphan in Nov 2023. Found in the slurry river of a mine in Phalaboraw. Handed over to CARE who brought to us. Fostered by Karla.', ''),
    ('Atlas', 'male', '26609', 'Koko', 2023, array['https://i.ibb.co/xD4brFX/atlas-koko-feb2024.jpg']::text[], 'Arrived as an orphan in Oct 2023. Mother was shot by a farmer. Fostered by Yllena.', ''),
    ('Samber', 'male', '41181', 'Koko', 2023, array['https://i.ibb.co/Xy8Pn6y/samber-koko-mar2024.jpg']::text[], 'Arrived as an orphan in Nov 2023. History unknown, was at Chimp Eden for a week before arrival at VMF. Arrived with suspected case of ringworm. Fostered by Kara.', ''),
    ('Riccardo', 'male', '26665', 'Koko', 2023, array['https://i.ibb.co/hX8Zs3c/riccardo-koko-mar2024.jpg']::text[], 'Arrived as an orphan in Oct 2023. History unknown, was handed in to a vet in Polokwane and then brought to us by Whelmi. Fostered by Panacur.', ''),
