    ('Ariel', 'female', '', 'Royal', 2018, array['https://i.ibb.co/9tdzxk8/ariel-royal-may2023-min.webp', 'https://i.ibb.co/0rqwz3m/ariel-royal-may2024-min.webp']::text[], 'Born 2018 in troop. Mother unknown. Previously known by nickname ‘Nugget’.', ''),
